const inputs = $input.all();

function extractBudget(text) {
  if (!text) return { type: 'unknown', raw: 'Not specified', amount: 0 };
  const fixed = text.match(/Budget:\s*\$?([\d,]+)/i) || text.match(/\(\$?([\d,]+)\)$/);
  if (fixed) {
    const val = parseInt(fixed[1].replace(/,/g, ''), 10);
    return { type: 'fixed', raw: `$${val}`, amount: val };
  }
  const hourly = text.match(/\$([\d.]+)\s*\/hr/i);
  if (hourly) {
    const val = parseFloat(hourly[1]);
    return { type: 'hourly', raw: `$${val}/hr`, amount: val };
  }
  return { type: 'unknown', raw: 'Not specified', amount: 0 };
}

function extractClient(text) {
  const ratingMatch = text ? text.match(/([\d.]+)\s*of\s*5/i) : null;
  const spentMatch = text ? text.match(/\$([\d,]+)\+?\s*spent/i) : null;
  return {
    rating: ratingMatch ? parseFloat(ratingMatch[1]) : null,
    spent: spentMatch ? parseInt(spentMatch[1].replace(/,/g, ''), 10) : 0,
    paymentVerified: /payment\s+verified/i.test(text || '')
  };
}

return inputs.map(item => {
  const json = item.json;
  const rawDesc = json.content || json.contentSnippet || json.description || '';
  const cleanDesc = rawDesc.replace(/<[^>]*>/g, '').replace(/&amp;/g, '&').replace(/&nbsp;/g, ' ').trim();
  const url = json.link || json.url || '';
  const jobIdMatch = url.match(/~([a-zA-Z0-9]+)/);
  const jobId = jobIdMatch ? jobIdMatch[1] : (json.guid || `job_${Math.random().toString(36).substring(7)}`);

  return {
    json: {
      jobId,
      jobTitle: json.title || 'Untitled Upwork Opportunity',
      jobUrl: url,
      jobDescription: cleanDesc,
      postedAt: json.pubDate || new Date().toISOString(),
      budget: extractBudget(cleanDesc),
      client: extractClient(cleanDesc),
      skillsRequired: json.categories || json.skills || ''
    }
  };
});

const item = $input.first().json;

const CORE_SKILLS = ['n8n', 'automation', 'workflow', 'ai', 'gpt', 'openai', 'llm', 'api integration', 'python', 'javascript', 'airtable'];
const text = `${item.jobTitle} ${item.jobDescription} ${item.skillsRequired}`.toLowerCase();

const matchedSkills = CORE_SKILLS.filter(s => text.includes(s));

// 1. Skill Score (0-30)
let skillScore = matchedSkills.length >= 4 ? 30 : matchedSkills.length * 7;

// 2. Client Score (0-25)
let clientScore = 10;
if (item.client.rating >= 4.8) clientScore += 10;
else if (item.client.rating >= 4.5) clientScore += 7;
if (item.client.spent >= 10000) clientScore += 5;

// 3. Budget Score (0-20)
let budgetScore = item.budget.amount >= 500 || item.budget.type === 'hourly' ? 18 : 10;

// 4. Clarity & Strategic (0-25)
let clarityScore = item.jobDescription.length > 400 ? 15 : 8;
let strategicScore = text.includes('n8n') || text.includes('openai') ? 10 : 5;

const totalScore = Math.min(100, skillScore + clientScore + budgetScore + clarityScore + strategicScore);

let priority = 'Ignore';
if (totalScore >= 85) priority = 'High Priority';
else if (totalScore >= 70) priority = 'Worth Reviewing';
else if (totalScore >= 50) priority = 'Low Priority';

return [{
  json: {
    ...item,
    matchedSkills,
    totalScore,
    priority
  }
}];

const job = $input.first().json;

const prompt = `Write a concise, high-converting Upwork proposal for:
JOB: ${job.jobTitle}
BUDGET: ${job.budget.raw}
DESCRIPTION:
${job.jobDescription}

STRICT RULES:
- No generic greetings.
- Hook with a specific technical detail.
- Highlight past experience building fault-tolerant n8n workflows handling 20K+ daily operations.
- Offer a clear 3-step solution.
- Soft CTA at the end. Keep under 180 words.`;

return [{
  json: {
    ...job,
    openAiPrompt: prompt
  }
}];

const input = $input.first().json;
const job = $('0-100 Opportunity Intelligence Engine').first().json;
const proposalText = input.text || input.message?.content || input.output?.[0]?.content?.[0]?.text || 'Proposal generated.';

const slackMsg = `🚀 *NEW HIGH-MATCH UPWORK OPPORTUNITY*

📌 *Title:* ${job.jobTitle}
📊 *Score:* ${job.totalScore}/100 ([ *${job.priority}* ])
💰 *Budget:* ${job.budget.raw}
⭐ *Client Rating:* ${job.client.rating || 'New Client'}
🛠️ *Matched Skills:* ${job.matchedSkills.join(', ')}
🔗 *Link:* ${job.jobUrl}

📝 *AI Generated Proposal Draft:*
\`\`\`
${proposalText}
\`\`\`

👤 *Human Review Action Required:* [ Approve & Submit ] | [ Edit Proposal ] | [ Reject ]`;

return [{ json: { ...job, proposalText, slackMsg } }];
